--
-- Name: get_collection_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_collection_stats(target_collection_id uuid) RETURNS TABLE(collection_id uuid, collection_name character varying, document_count bigint, chunk_count bigint, total_file_size bigint, avg_chunks_per_document numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        col.id AS collection_id,
        col.name AS collection_name,
        COUNT(DISTINCT d.id) AS document_count,
        COUNT(c.id) AS chunk_count,
        COALESCE(SUM(d.file_size), 0) AS total_file_size,
        CASE 
            WHEN COUNT(DISTINCT d.id) > 0 
            THEN ROUND(COUNT(c.id)::numeric / COUNT(DISTINCT d.id), 2)
            ELSE 0
        END AS avg_chunks_per_document
    FROM collections col
    LEFT JOIN documents d ON col.id = d.collection_id AND d.is_deleted = FALSE
    LEFT JOIN chunks c ON d.id = c.document_id
    WHERE col.id = target_collection_id
    GROUP BY col.id, col.name;
END;
$$;


--
-- Name: search_similar_chunks(public.vector, double precision, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_similar_chunks(query_embedding public.vector, match_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 10, filter_collection_id uuid DEFAULT NULL::uuid) RETURNS TABLE(chunk_id uuid, document_id uuid, collection_id uuid, content text, section_title character varying, similarity double precision, document_title character varying, document_metadata jsonb, collection_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id AS chunk_id,
        c.document_id,
        d.collection_id,
        c.content,
        c.section_title,
        1 - (c.embedding <=> query_embedding) AS similarity,
        d.title AS document_title,
        d.metadata AS document_metadata,
        col.name AS collection_name
    FROM chunks c
    JOIN documents d ON c.document_id = d.id
    JOIN collections col ON d.collection_id = col.id
    WHERE 
        (filter_collection_id IS NULL OR d.collection_id = filter_collection_id)
        AND d.is_deleted = FALSE
        AND d.status = 'completed'
        AND (1 - (c.embedding <=> query_embedding)) > match_threshold
    ORDER BY c.embedding <=> query_embedding
    LIMIT match_count;
END;
$$;


--
-- Name: update_collection_document_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_collection_document_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE collections 
        SET document_count = document_count + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = NEW.collection_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE collections 
        SET document_count = document_count - 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = OLD.collection_id;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: update_collection_total_chunks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_collection_total_chunks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- When new chunk is inserted, increment total_chunks in collection
        UPDATE collections 
        SET total_chunks = total_chunks + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = (
            SELECT collection_id 
            FROM documents 
            WHERE id = NEW.document_id
        );
    ELSIF TG_OP = 'DELETE' THEN
        -- When chunk is deleted, decrement total_chunks in collection
        UPDATE collections 
        SET total_chunks = total_chunks - 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = (
            SELECT collection_id 
            FROM documents 
            WHERE id = OLD.document_id
        );
    END IF;
    RETURN NULL;
END;
$$;


